// contractSchemas are the schema names the ingest contract owns: when huma generates a schema
// with the same name (the Go problem type), the contract version is published.
var contractSchemas = map[string]bool{"Problem": true}

// specHandlers serves the complete OpenAPI document (query operations generated by huma,
// ingest operations from the published contract, and /health) as JSON and YAML. The document
// is built on the first request, after every operation is registered.
func specHandlers(api huma.API) (jsonHandler, yamlHandler http.HandlerFunc) {
	build := sync.OnceValues(func() ([2][]byte, error) {
		doc, err := buildSpec(api)
		if err != nil {
			return [2][]byte{}, err
		}
		j, err := json.Marshal(doc)
		if err != nil {
			return [2][]byte{}, err
		}
		y, err := yaml.Marshal(doc)
		return [2][]byte{j, y}, err
	})
	serve := func(i int, contentType string) http.HandlerFunc {
		return func(w http.ResponseWriter, _ *http.Request) {
			docs, err := build()
			if err != nil {
				slog.Error("build OpenAPI document", "error", err)
				writeProblem(w, http.StatusInternalServerError, "internal error")
				return
			}
			w.Header().Set("Content-Type", contentType)
			w.Header().Set("X-Content-Type-Options", "nosniff")
			_, _ = w.Write(docs[i])
		}
	}
	return serve(0, "application/openapi+json"), serve(1, "application/openapi+yaml")
}

func buildSpec(api huma.API) (map[string]any, error) {
	documentQueryErrors(api.OpenAPI())

	raw, err := json.Marshal(api.OpenAPI())
	if err != nil {
		return nil, err
	}
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil, err
	}
	var ingest map[string]any
	if err := yaml.Unmarshal(docs.IngestOpenAPI, &ingest); err != nil {
		return nil, fmt.Errorf("ingest contract: %w", err)
	}
	if err := mergeIngest(doc, ingest); err != nil {
		return nil, err
	}
	paths(doc)["/health"] = map[string]any{"get": healthOperation}
	doc["servers"] = []any{map[string]any{"url": "/", "description": "This AUD instance"}}
	return doc, pruneSchemas(doc)
}

// pruneSchemas removes component schemas nothing references, such as the one huma generated
// for the Go problem type before the contract's Problem replaced it.
func pruneSchemas(doc map[string]any) error {
	schemas := asMap(asMap(doc["components"])["schemas"])
	for removed := true; removed; {
		removed = false
		raw, err := json.Marshal(doc)
		if err != nil {
			return err
		}
		for name := range schemas {
			if !strings.Contains(string(raw), `"#/components/schemas/`+name+`"`) {
				delete(schemas, name)
				removed = true
			}
		}
	}
	return nil
}

// documentQueryErrors finishes the huma operations: it drops 422 (validation errors are
// answered with 400), adds an example to the 200 response and to every error, and the
// challenge header to 401.
func documentQueryErrors(oapi *huma.OpenAPI) {
	for _, item := range oapi.Paths {
		op := item.Get
		if op == nil {
			continue
		}
		delete(op.Responses, "422")
		if mt := op.Responses["200"].Content["application/json"]; mt != nil {
			mt.Examples = successExamples[op.OperationID]
		}
		roles, _ := op.Metadata[metaRoles].([]string)
		for code, resp := range op.Responses {
			if mt := resp.Content["application/problem+json"]; mt != nil {
				mt.Example = exampleProblem(code, op, roles)
			}
		}
		if resp := op.Responses["401"]; resp != nil {
			resp.Description = "Missing, malformed, expired or badly signed bearer token. The cause is not disclosed."
			resp.Headers = map[string]*huma.Param{"WWW-Authenticate": {
				Description: `Bearer challenge, e.g. Bearer realm="aud", error="invalid_token".`,
				Schema:      &huma.Schema{Type: huma.TypeString},
			}}
		}
		if resp := op.Responses["403"]; resp != nil {
			resp.Description = "Valid token without the required role (" + strings.Join(roles, " or ") + ")."
		}
	}
}

