func exampleProblem(code string, op *huma.Operation, roles []string) problem {
	p := problem{Type: "about:blank"}
	_, _ = fmt.Sscan(code, &p.Status)
	p.Title = http.StatusText(p.Status)
	switch p.Status {
	case http.StatusBadRequest:
		p.Detail = "validation failed"
		field := "id"
		if len(op.Parameters) > 0 {
			field = op.Parameters[0].Name
		}
		p.Errors = []domain.FieldError{{Field: field, Message: "invalid value"}}
	case http.StatusUnauthorized:
		p.Detail = bearerDetail
	case http.StatusForbidden:
		p.Detail = "this operation requires one of the roles: " + strings.Join(roles, ", ")
	case http.StatusNotFound:
		p.Detail = "event not found"
	default:
		p.Detail = "internal error"
	}
	return p
}

// mergeIngest adds the operations and components of the ingest contract to doc. The contract's
// paths are relative to its server URL (/api/v1) and inherit its top-level security.
func mergeIngest(doc, ingest map[string]any) error {
	prefix := ""
	if servers, _ := ingest["servers"].([]any); len(servers) > 0 {
		server, _ := servers[0].(map[string]any)
		u, err := url.Parse(fmt.Sprint(server["url"]))
		if err != nil {
			return fmt.Errorf("ingest contract server: %w", err)
		}
		prefix = strings.TrimSuffix(u.Path, "/")
	}

	all := paths(doc)
	for path, item := range asMap(ingest["paths"]) {
		target := asMap(all[prefix+path])
		if target == nil {
			target = map[string]any{}
			all[prefix+path] = target
		}
		for method, op := range asMap(item) {
			if _, taken := target[method]; taken {
				return fmt.Errorf("ingest contract: %s %s is already defined", method, prefix+path)
			}
			o := asMap(op)
			if _, ok := o["security"]; !ok {
				o["security"] = ingest["security"]
			}
			o["tags"] = []any{"Ingest"}
			target[method] = o
		}
	}

	components := asMap(doc["components"])
	for section, entries := range asMap(asMap(ingest["components"])) {
		dst := asMap(components[section])
		if dst == nil {
			dst = map[string]any{}
			components[section] = dst
		}
		for name, v := range asMap(entries) {
			if _, taken := dst[name]; taken && (section != "schemas" || !contractSchemas[name]) {
				return fmt.Errorf("ingest contract: components.%s.%s is already defined", section, name)
			}
			dst[name] = v
		}
	}

	info := asMap(doc["info"])
	info["description"] = apiDescription + "\n\n## Ingest\n\n" + fmt.Sprint(asMap(ingest["info"])["description"])
	doc["tags"] = []any{
		map[string]any{"name": "Ingest", "description": "Signed with HMAC-SHA256 by the emitting modules (ingest contract)."},
		map[string]any{"name": queryTag, "description": "Bearer JWT with the auditor or admin role."},
		map[string]any{"name": "Health", "description": "Liveness probe."},
	}
	return nil
}

func paths(doc map[string]any) map[string]any {
	p := asMap(doc["paths"])
	if p == nil {
		p = map[string]any{}
		doc["paths"] = p
	}
	return p
}

func asMap(v any) map[string]any {
	m, _ := v.(map[string]any)
	return m
}

const apiDescription = `AUD (module 11 of MediNet-Core) keeps an append-only, hash-chained log of the security
events of every module.

- **Ingest** (` + "`POST /api/v1/events`, `POST /api/v1/events/batch`" + `): modules send events signed with
  HMAC-SHA256 (security schemes audClientId, audTimestamp and audSignature).
- **Query** (` + "`GET /api/v1/...`" + `): auditors and administrators read the log with a bearer JWT
  (security scheme bearer).

Every error is an RFC 7807 problem (` + "`application/problem+json`" + `); invalid parameters are answered
with 400 and listed in ` + "`errors[].field`" + `.`

